using DomainModel.ViewModels.City; using Framework.Common.Seo; namespace DataAccess.Repositories.City; public static class CityMapper { public static DomainModel.Models.City ToEntity(CityAddEditModel m)=>new(){CityName=m.CityName.Trim(),ProvinceID=m.ProvinceID,IsActive=m.IsActive,DisplayOrder=m.DisplayOrder,Slug=string.IsNullOrWhiteSpace(m.Slug)?null:SeoHelper.ToSlug(m.Slug),SeoTitle=m.SeoTitle,SeoDescription=m.SeoDescription,SeoKeywords=m.SeoKeywords,CanonicalUrl=m.CanonicalUrl,OpenGraphImageUrl=m.OpenGraphImageUrl,IsIndexable=m.IsIndexable,IsFollow=m.IsFollow}; public static void MapForUpdate(CityAddEditModel m,DomainModel.Models.City e){e.CityName=m.CityName.Trim();e.ProvinceID=m.ProvinceID;e.IsActive=m.IsActive;e.DisplayOrder=m.DisplayOrder;e.Slug=string.IsNullOrWhiteSpace(m.Slug)?null:SeoHelper.ToSlug(m.Slug);e.SeoTitle=m.SeoTitle;e.SeoDescription=m.SeoDescription;e.SeoKeywords=m.SeoKeywords;e.CanonicalUrl=m.CanonicalUrl;e.OpenGraphImageUrl=m.OpenGraphImageUrl;e.IsIndexable=m.IsIndexable;e.IsFollow=m.IsFollow;} }
